        title: `15. CONTACT US`,
        rawTitle: `CONTACT US`,
        contentHtml: `<p>For exchange requests, Program queries, or assistance, please contact:</p><table><tr><td><p><strong>Company</strong></p></td><td><p>Aura Jewels Private Limited (Brand: Aura Jewels)</p></td></tr><tr><td><p><strong>Email</strong></p></td><td><p>info@aurajewels.com</p></td></tr><tr><td><p><strong>Phone</strong></p></td><td><p>+91 98765 43210</p></td></tr><tr><td><p><strong>WhatsApp</strong></p></td><td><p>+91 98765 43210</p></td></tr><tr><td><p><strong>Address</strong></p></td><td><p>Plot No. 102, Bandra Kurla Complex, Bandra East, Mumbai - 400051, Maharashtra, India</p></td></tr><tr><td><p><strong>Business Hours</strong></p></td><td><p>Monday to Saturday, 9:30 AM – 5:30 PM IST (excluding public holidays)</p></td></tr></table><p><em>© Aura Jewels Private Limited. All Rights Reserved. Unauthorised reproduction of this Policy is prohibited.</em></p>`
